[$students,$rooms,$seats]=fixture(25,1);$seats[0]['state']='disabled';$seats[1]['state']='aisle';$rooms[0]['capacity']=25;$map=(new SeatingSolver())->solve($students,$rooms,$seats,'none');ok(!in_array(1,array_column($map,'seat_id'))&&!in_array(2,array_column($map,'seat_id')),'disabled and aisle excluded');
$rooms[0]['capacity']=24;$rejected=false;try{(new SeatingSolver())->solve($students,$rooms,$seats);}catch(RuntimeException $e){$rejected=true;}ok($rejected,'room quota enforced');
[$students,$rooms,$seats]=fixture(10,1);$students[0]['needs_access']=1;$map=(new SeatingSolver())->solve($students,$rooms,$seats);$student1=array_values(array_filter($map,fn($a)=>$a['student_id']===1))[0];$byId=array_column($seats,null,'id');ok((bool)$byId[$student1['seat_id']]['accessible'],'access needs satisfied');
foreach($seats as &$seat)$seat['accessible']=0;unset($seat);$rejected=false;try{(new SeatingSolver())->solve($students,$rooms,$seats);}catch(RuntimeException $e){$rejected=true;}ok($rejected,'access infeasible rejected');
