$rejected=false;try{solve_monitors(array_slice($people,0,2),[['id'=>1,'required_monitors'=>2],['id'=>2,'required_monitors'=>2]],120);}catch(RuntimeException $e){$rejected=true;}ok($rejected,'monitor shortage rejected');
